import { test } from 'node:test';
import assert from 'node:assert/strict';
import { overdueInvoices, vatSummary } from '../src/reports.js';
import { createInvoice, issueInvoice } from '../src/invoices.js';
import { recordPayment } from '../src/payments.js';

test('overdueInvoices: returns empty array for no invoices', () => {
  const result = overdueInvoices([], '2025-03-01');

  assert.deepEqual(result, []);
});

test('overdueInvoices: returns empty array for no overdue invoices', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = issueInvoice(invoiceResult.value, []).value;

  // Invoice due date is 2025-03-16 (NET30), so not overdue on 2025-03-15
  const result = overdueInvoices([invoice], '2025-03-15');

  assert.deepEqual(result, []);
});

test('overdueInvoices: includes invoice with dueDate before asOf', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = issueInvoice(invoiceResult.value, []).value;

  // Invoice due date is 2025-03-16, so overdue on 2025-03-17
  const result = overdueInvoices([invoice], '2025-03-17');

  assert.equal(result.length, 1);
  assert.equal(result[0].number, invoice.number);
});

test('overdueInvoices: excludes draft invoices', () => {
  const invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = invoiceResult.value;

  const result = overdueInvoices([invoice], '2025-04-01');

  assert.deepEqual(result, []);
});

test('overdueInvoices: includes partially_paid invoices', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  let invoice = issueInvoice(invoiceResult.value, []).value;

  const paymentResult = recordPayment(invoice, { amount: 50000, date: '2025-03-01' });
  assert.equal(paymentResult.ok, true);
  invoice = paymentResult.value;

  assert.equal(invoice.status, 'partially_paid');

  const result = overdueInvoices([invoice], '2025-03-17');

  assert.equal(result.length, 1);
  assert.equal(result[0].number, invoice.number);
});

test('overdueInvoices: calculates daysOverdue correctly', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = issueInvoice(invoiceResult.value, []).value;

  // Due date is 2025-03-16, overdue report on 2025-03-26 = 10 days overdue
  const result = overdueInvoices([invoice], '2025-03-26');

  assert.equal(result.length, 1);
  assert.equal(result[0].daysOverdue, 10);
});

test('overdueInvoices: includes customerId and dueDate', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = issueInvoice(invoiceResult.value, []).value;

  const result = overdueInvoices([invoice], '2025-03-20');

  assert.equal(result.length, 1);
  assert.equal(result[0].customerId, 'C-002');
  assert.equal(result[0].dueDate, invoice.dueDate);
});

test('overdueInvoices: includes due amount from balanceDue', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  let invoice = issueInvoice(invoiceResult.value, []).value;

  const paymentResult = recordPayment(invoice, { amount: 50000, date: '2025-03-01' });
  assert.equal(paymentResult.ok, true);
  invoice = paymentResult.value;

  const result = overdueInvoices([invoice], '2025-03-20');

  assert.equal(result.length, 1);
  // Total is 114950, paid 50000, so due is 64950
  const due = result[0].due;
  assert(due > 0);
  assert(due < 114950);
});

test('overdueInvoices: sorts by daysOverdue descending', () => {
  let invoice1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-01',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  let invoice2Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-10',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  let invoice3Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-20',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert.equal(invoice1Result.ok, true);
  assert.equal(invoice2Result.ok, true);
  assert.equal(invoice3Result.ok, true);

  let invoice1 = issueInvoice(invoice1Result.value, []).value;
  let invoice2 = issueInvoice(invoice2Result.value, ['2025-0001']).value;
  let invoice3 = issueInvoice(invoice3Result.value, ['2025-0001', '2025-0002']).value;

  const result = overdueInvoices([invoice3, invoice1, invoice2], '2025-03-25');

  assert.equal(result.length, 3);
  // invoice1 due 2025-03-03, days overdue = 22
  // invoice2 due 2025-03-12, days overdue = 13
  // invoice3 due 2025-03-22, days overdue = 3
  assert.equal(result[0].number, invoice1.number);
  assert.equal(result[1].number, invoice2.number);
  assert.equal(result[2].number, invoice3.number);
});

test('overdueInvoices: handles mixed issued and partially_paid', () => {
  let invoice1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-10',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  let invoice2Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoice1Result.ok, true);
  assert.equal(invoice2Result.ok, true);

  let invoice1 = issueInvoice(invoice1Result.value, []).value;
  let invoice2 = issueInvoice(invoice2Result.value, ['2025-0001']).value;

  const paymentResult = recordPayment(invoice2, { amount: 50000, date: '2025-03-01' });
  assert.equal(paymentResult.ok, true);
  invoice2 = paymentResult.value;

  const result = overdueInvoices([invoice1, invoice2], '2025-03-25');

  assert.equal(result.length, 2);
  assert(result.some(inv => inv.number === invoice1.number));
  assert(result.some(inv => inv.number === invoice2.number));
});

test('overdueInvoices: handles multiple overdue invoices for same customer', () => {
  const invoices = [];

  for (let i = 0; i < 5; i++) {
    const date = `2025-02-${String(10 + i).padStart(2, '0')}`;
    let invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: date,
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    });
    assert.equal(invoiceResult.ok, true);

    const issued = issueInvoice(invoiceResult.value, invoices.map(inv => inv.number || '')).value;
    invoices.push(issued);
  }

  const result = overdueInvoices(invoices, '2025-03-30');

  assert.equal(result.length, 5);
  assert.equal(result[0].customerId, 'C-001');
});

test('overdueInvoices: handles invoices from different customers', () => {
  let invoice1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-10',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  let invoice2Result = createInvoice({
    customerId: 'C-002',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  let invoice3Result = createInvoice({
    customerId: 'C-003',
    issueDate: '2025-02-20',
    lines: [{ sku: 'DEV-HOUR', qty: 3 }],
  });

  assert.equal(invoice1Result.ok, true);
  assert.equal(invoice2Result.ok, true);
  assert.equal(invoice3Result.ok, true);

  let invoice1 = issueInvoice(invoice1Result.value, []).value;
