  let invoice2 = issueInvoice(invoice2Result.value, ['2025-0001']).value;

  const paymentResult = recordPayment(invoice2, { amount: 50000, date: '2025-03-01' });
  assert.equal(paymentResult.ok, true);
  invoice2 = paymentResult.value;

  const result = overdueInvoices([invoice1, invoice2], '2025-03-25');

  assert.equal(result.length, 2);
  assert(result.some(inv => inv.number === invoice1.number));
  assert(result.some(inv => inv.number === invoice2.number));
});

test('overdueInvoices: handles multiple overdue invoices for same customer', () => {
  const invoices = [];

  for (let i = 0; i < 5; i++) {
    const date = `2025-02-${String(10 + i).padStart(2, '0')}`;
    let invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: date,
      lines: [{ sku: 'DEV-HOUR', qty: 1 }],
    });
    assert.equal(invoiceResult.ok, true);

    const issued = issueInvoice(invoiceResult.value, invoices.map(inv => inv.number || '')).value;
    invoices.push(issued);
  }

  const result = overdueInvoices(invoices, '2025-03-30');

  assert.equal(result.length, 5);
  assert.equal(result[0].customerId, 'C-001');
});

test('overdueInvoices: handles invoices from different customers', () => {
  let invoice1Result = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-10',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  let invoice2Result = createInvoice({
