  const result = overdueInvoices([invoice], '2025-03-20');

  assert.equal(result.length, 1);
  const overdue = result[0];
  assert('number' in overdue);
  assert('customerId' in overdue);
  assert('dueDate' in overdue);
  assert('daysOverdue' in overdue);
  assert('due' in overdue);
  assert.equal(Object.keys(overdue).length, 5);
});

test('vatSummary: returns empty array for no invoices', () => {
