  assert.equal(paymentResult.ok, true);
  invoice = paymentResult.value;

  const result = vatSummary([invoice]);

  assert.equal(result.length, 1);
  // Base and VAT should be same as if it was just issued (no discount for standard tier)
  assert.equal(result[0].base, 95000);
  assert.equal(result[0].vat, 19950);
});

test('vatSummary: returns rate, base, and vat fields', () => {
  let invoiceResult = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-02-14',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  });

  assert.equal(invoiceResult.ok, true);
  const invoice = issueInvoice(invoiceResult.value, []).value;

  const result = vatSummary([invoice]);

  assert.equal(result.length, 1);
  const summary = result[0];
  assert('rate' in summary);
  assert('base' in summary);
  assert('vat' in summary);
  assert.equal(Object.keys(summary).length, 3);
});
